// src/components/Navbar.js

import React from 'react';
import { Link } from 'react-router-dom';
// import '../App.css'; // 공통 스타일이 App.css에 있다면 가져옵니다.

function Navbar() {
  // HTML <style> 태그의 CSS 클래스를 여기서 사용하거나, App.css에 넣어주세요.
  return (
    <header className="navbar" style={{ /* 여기에 CSS 스타일을 직접 넣거나, */ }}> 
      <div className="navbar-left">
        {/* home.html 대신 "/" 경로 사용 */}
        <Link to="/" className="logo">Arch-GPT</Link>
        <nav>
          <ul>
            {/* a 태그 대신 Link 컴포넌트와 React Router 경로 사용 */}
            <li><Link to="/projects">My Project</Link></li>
            <li><Link to="/resources">Resources</Link></li>
            <li><Link to="/library">Library</Link></li>
            <li><Link to="/about">About Us</Link></li>
          </ul>
        </nav>
      </div>
      <div className="navbar-nav ms-auto">
        {/* onclick="location.href='login.html'" 대신 Link 사용 또는 모달 함수 호출 */}
        <button className="login-button">Login</button>
      </div>
    </header>
  );
}

export default Navbar;
